/**
 * main.js for a website generated by the Adawaty Website Builder.
 * Intentionally minimal: no analytics, no tracking, no external requests,
 * no dependency on Adawaty. Only included in the export when the site
 * actually has a contact form or the nav needs a mobile toggle.
 */
(function () {
    'use strict';

    var navToggle = document.querySelector('.nav-toggle');
    var navLinks = document.querySelector('.nav-links');
    if (navToggle && navLinks) {
        navToggle.addEventListener('click', function () {
            var isOpen = navLinks.classList.toggle('is-open');
            navToggle.setAttribute('aria-expanded', String(isOpen));
        });
    }

    var demoForms = document.querySelectorAll('[data-demo-form]');
    demoForms.forEach(function (form) {
        form.addEventListener('submit', function (event) {
            event.preventDefault();
            var result = form.querySelector('[data-demo-form-result]');
            if (result) {
                var isArabic = document.documentElement.lang === 'ar';
                result.textContent = isArabic
                    ? 'هذا نموذج تجريبي — لم يتم إرسال أي بيانات.'
                    : 'This is a demo form \u2014 no data was actually sent.';
                result.hidden = false;
            }
            form.reset();
        });
    });
})();
